        MDEEvidenceAddPAIR_INDEX(builder, self.PAIR_INDEX)
        MDEEvidenceAddSTEP_IN_TRACK_M_S(builder, self.STEP_IN_TRACK_M_S)
        MDEEvidenceAddSTEP_PLANE_M_S(builder, self.STEP_PLANE_M_S)
        MDEEvidenceAddTHRESHOLD_IN_TRACK_M_S(builder, self.THRESHOLD_IN_TRACK_M_S)
        MDEEvidenceAddTHRESHOLD_PLANE_M_S(builder, self.THRESHOLD_PLANE_M_S)
        MDEEvidenceAddCROSSING_AT_EDGE(builder, self.CROSSING_AT_EDGE)
        MDEEvidenceAddSPAN_START_MS(builder, self.SPAN_START_MS)
        MDEEvidenceAddSPAN_STOP_MS(builder, self.SPAN_STOP_MS)
        MDEEvidenceAddGLR_STATISTIC(builder, self.GLR_STATISTIC)
        MDEEvidenceAddSTEP_M_S(builder, self.STEP_M_S)
        MDEEvidenceAddSTEP_SD_M_S(builder, self.STEP_SD_M_S)
        MDEEvidenceAddSIGMA_M_S(builder, self.SIGMA_M_S)
        MDEEvidenceAddTREND_M_S_PER_DAY(builder, self.TREND_M_S_PER_DAY)
        MDEEvidenceAddOLD_LEVEL_SET_MS(builder, self.OLD_LEVEL_SET_MS)
        MDEEvidenceAddNEW_LEVEL_SET_MS(builder, self.NEW_LEVEL_SET_MS)
        MDEEvidenceAddTIME_BASIS(builder, self.TIME_BASIS)
        MDEEvidenceAddPLANE_GLR_STATISTIC(builder, self.PLANE_GLR_STATISTIC)
        MDEEvidenceAddPLANE_STEP_M_S(builder, self.PLANE_STEP_M_S)
        MDEEvidenceAddRATE_CHANGE_M_S_PER_DAY(builder, self.RATE_CHANGE_M_S_PER_DAY)
        MDEEvidenceAddRATE_CHANGE_SD(builder, self.RATE_CHANGE_SD)
        MDEEvidenceAddTREND_BEFORE_M_S_PER_DAY(builder, self.TREND_BEFORE_M_S_PER_DAY)
        if self.COMPONENTS is not None:
            MDEEvidenceAddCOMPONENTS(builder, COMPONENTS)
        MDEEvidenceAddKEPT(builder, self.KEPT)
        MDEEvidence = MDEEvidenceEnd(builder)
        return MDEEvidence
